// Tests derived from the BSV node v1.2.0 Chronicle upgrade functional test
// scriptSig_checksig.py:
// https://github.com/bitcoin-sv/bitcoin-sv/tree/172c8fa38cce30cf4df0327b33c7418ea6289de8/test/functional/chronicle_upgrade_tests
//
// Post-Chronicle, a CHECKSIG or CHECKMULTISIG executing in the unlocking
// script signs everything from the most recent OP_CODESEPARATOR to the end of
// the unlocking script plus the whole locking script.

package interpreter

import (
	"encoding/hex"
	"testing"

	"github.com/stretchr/testify/require"

	ec "github.com/bsv-blockchain/go-sdk/primitives/ec"
	"github.com/bsv-blockchain/go-sdk/script"
	"github.com/bsv-blockchain/go-sdk/transaction"
	sighash "github.com/bsv-blockchain/go-sdk/transaction/sighash"
)

// scriptSigCheckSigTx builds a version 2 transaction spending a
// <utxoPubKey> OP_CHECKSIG output with the unlocking script
//
//	<utxoSig> <pre...> <sigs...> OP_CODESEPARATOR <check>
//
// where each of sigs signs <check> followed by the locking script.
func scriptSigCheckSigTx(t *testing.T, flag sighash.Flag, pre []interface{}, check *script.Script, keys ...*ec.PrivateKey) (*transaction.Transaction, *transaction.TransactionOutput) {
	t.Helper()
	utxoKey, utxoPubKey := chronicleKey("utxo")
	tx, prevOut := chronicleP2PKTx(t, utxoPubKey)
	lock := prevOut.LockingScript

	scriptCode := script.NewFromBytes(append(append([]byte{}, *check...), *lock...))
	parts := make([]interface{}, 0, len(pre)+len(keys)+2)
	parts = append(parts, chronicleSign(t, tx, lock, sighash.AllForkID, utxoKey))
	parts = append(parts, pre...)
	for _, key := range keys {
		parts = append(parts, chronicleSign(t, tx, scriptCode, flag, key))
	}
	parts = append(parts, script.OpCODESEPARATOR)
	unlock := buildScript(t, parts...)
	*unlock = append(*unlock, *check...)
	tx.Inputs[0].UnlockingScript = unlock
	return tx, prevOut
}

func TestChronicleScriptSigCheckSig(t *testing.T) {
	key0, pubKey0 := chronicleKey("secret0")
	key1, pubKey1 := chronicleKey("secret1")
	_, pubKey2 := chronicleKey("secret2")

	flags := map[string]sighash.Flag{
		"NTDA": sighash.AllForkID,
		"OTDA": sighash.AllForkID | sighash.Chronicle,
	}
	checks := map[string]func(*testing.T, sighash.Flag) (*transaction.Transaction, *transaction.TransactionOutput){
		// UTXOSig, Key0Sig, OCS, PubKey0, CHECKSIGVERIFY | UTXOKey, CHECKSIG
		"CHECKSIG": func(t *testing.T, flag sighash.Flag) (*transaction.Transaction, *transaction.TransactionOutput) {
			check := buildScript(t, pubKey0, script.OpCHECKSIGVERIFY)
			return scriptSigCheckSigTx(t, flag, nil, check, key0)
		},
		// UTXOSig, OP_0, Key0Sig, Key1Sig, OCS, OP_2, PubKey0, PubKey1, PubKey2, OP_3, CHECKMULTISIGVERIFY | UTXOKey, CHECKSIG
		"CHECKMULTISIG": func(t *testing.T, flag sighash.Flag) (*transaction.Transaction, *transaction.TransactionOutput) {
			check := buildScript(t, script.Op2, pubKey0, pubKey1, pubKey2, script.Op3, script.OpCHECKMULTISIGVERIFY)
			return scriptSigCheckSigTx(t, flag, []interface{}{script.Op0}, check, key0, key1)
		},
	}

	for checkName, build := range checks {
		for flagName, flag := range flags {
			t.Run(checkName+"/"+flagName, func(t *testing.T) {
				tx, prevOut := build(t, flag)

				err := NewEngine().Execute(WithTx(tx, 0, prevOut), WithForkID(), WithAfterChronicle())
				require.NoError(t, err, "post-Chronicle the check signs the rest of the unlocking script plus the locking script")

				// Pre-Chronicle the node rejects any non-push unlocking script;
				// without that flag the check still signs only the unlocking script.
				err = NewEngine().Execute(WithTx(tx, 0, prevOut), WithForkID(), WithAfterGenesis())
				require.Error(t, err)
			})
		}
	}
}

// TestChronicleScriptSigCheckSigMainnet replays input 0 of mainnet transaction
// 3332aa2b0cb7dce2e3a9593e9f29749b8bd0f7d8392cae4d341f678c33bbc50e (block
// 961143). Its unlocking script rebuilds its own sighash preimage, checks it
// with OP_PUSH_TX, and ends OP_CODESEPARATOR OP_CHECKSIGVERIFY OP_ENDIF, so the
// signature commits to OP_CHECKSIGVERIFY OP_ENDIF followed by the 1265-byte
// locking script it spends (b74756c1ff185cba38b54159e2e240d77e7d306ad15cb467006878fb5995c450:0).
func TestChronicleScriptSigCheckSigMainnet(t *testing.T) {
	tx, err := transaction.NewTransactionFromHex(chronicleScriptSigTxHex)
	require.NoError(t, err)
	lock, err := hex.DecodeString(chronicleScriptSigPrevLockHex)
	require.NoError(t, err)
	prevOut := &transaction.TransactionOutput{Satoshis: 1, LockingScript: script.NewFromBytes(lock)}

	require.NoError(t, NewEngine().Execute(WithTx(tx, 0, prevOut), WithForkID(), WithAfterChronicle()))
}

const (
	chronicleScriptSigTxHex       = ""
	chronicleScriptSigPrevLockHex = ""
)
